<?php

declare(strict_types=1);

namespace Anthropic\Files;

use Anthropic\Core\Attributes\Required;
use Anthropic\Core\Concerns\SdkModel;
use Anthropic\Core\Contracts\BaseModel;
use Anthropic\Core\Conversion\ConstantOf;

/**
 * The file has `downloadable: false`. Only files generated by a tool, such as the code execution tool, can be downloaded.
 *
 * @phpstan-type FileNotDownloadableErrorDetailsShape = array{
 *   errorCode: 'file_not_downloadable'
 * }
 */
final class FileNotDownloadableErrorDetails implements BaseModel
{
    /** @use SdkModel<FileNotDownloadableErrorDetailsShape> */
    use SdkModel;

    /** @var 'file_not_downloadable' $errorCode */
    #[Required('error_code', type: new ConstantOf('file_not_downloadable'))]
    public string $errorCode = 'file_not_downloadable';

    public function __construct()
    {
        $this->initialize();
    }

    /**
     * Construct an instance from the required parameters.
     *
     * You must use named parameters to construct any parameters with a default value.
     */
    public static function with(): self
    {
        return new self;
    }

    /**
     * @param 'file_not_downloadable' $errorCode
     */
    public function withErrorCode(string $errorCode): self
    {
        $self = clone $this;
        $self['errorCode'] = $errorCode;

        return $self;
    }
}
